import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import { DEFAULT_CLUSTER_THRESHOLD, absorbSmallClusters, agglomerative, averageLinkage, covered, relabelByFirstAppearance } from "../../src/diarization/clustering.js";
import { MERGE_GAP_SECONDS, MIN_SPEAKER_SECONDS, toTurns } from "../../src/diarization/diarizer.js";

/**
 * Generated by scripts/gen_analysis_fixtures.py from ynlibs.audio.speakers (SciPy's linkage and
 * fcluster).
 */
const f = JSON.parse(readFileSync(join(dirname(fileURLToPath(import.meta.url)), "..", "fixtures", "speakers.json"), "utf-8")) as {
  embeddings: number[][];
  chunks: [number, number][];
  agglomerative: { kwargs: Record<string, number>; labels: number[] }[];
  noisy: { embeddings: number[][]; cases: { kwargs: Record<string, number>; labels: number[] }[] };
  clustered: number[];
  absorbed: number[];
  turns: { speaker: string; start: number; end: number }[];
  covered: [[number, number][], number][];
  defaults: { cluster_threshold: number; min_speaker_seconds: number; merge_gap: number };
};

const rows = (m: number[][]) => m.map((r) => Float32Array.from(r));
const options = (k: Record<string, number>) => ({
  ...(k["threshold"] !== undefined ? { threshold: k["threshold"] } : {}),
  numSpeakers: k["num_speakers"] ?? null,
  minSpeakers: k["min_speakers"] ?? null,
  maxSpeakers: k["max_speakers"] ?? null,
});

describe("speakers, against ynlibs.audio.speakers", () => {
  it("keeps the Python defaults", () => {
    expect(DEFAULT_CLUSTER_THRESHOLD).toBe(f.defaults.cluster_threshold);
    expect(MIN_SPEAKER_SECONDS).toBe(f.defaults.min_speaker_seconds);
    expect(MERGE_GAP_SECONDS).toBe(f.defaults.merge_gap);
  });

  it("cuts the average-linkage tree as fcluster does", () => {
    const embeddings = rows(f.embeddings);
    for (const c of f.agglomerative) expect(agglomerative(embeddings, options(c.kwargs)), JSON.stringify(c.kwargs)).toEqual(c.labels);
    const noisy = rows(f.noisy.embeddings);
    for (const c of f.noisy.cases) expect(agglomerative(noisy, options(c.kwargs)), `noisy ${JSON.stringify(c.kwargs)}`).toEqual(c.labels);
  });

  it("absorbs the clusters holding under 5 s of speech, counted as a union", () => {
    const embeddings = rows(f.embeddings);
    const clustered = agglomerative(embeddings);
    expect(clustered).toEqual(f.clustered);
    const absorbed = absorbSmallClusters(embeddings, clustered, f.chunks, MIN_SPEAKER_SECONDS);
    expect(relabelByFirstAppearance(absorbed)).toEqual(f.absorbed);
    expect(toTurns(f.chunks, relabelByFirstAppearance(absorbed))).toEqual(f.turns);
    for (const [spans, seconds] of f.covered) expect(covered(spans)).toBeCloseTo(seconds, 12);
  });

  it("leaves the labels alone when every cluster, or none, is big enough", () => {
    const embeddings = rows(f.embeddings);
    const one = new Array<number>(embeddings.length).fill(0);
    expect(absorbSmallClusters(embeddings, one, f.chunks, 5)).toEqual(one);
    const clustered = agglomerative(embeddings);
    expect(absorbSmallClusters(embeddings, clustered, f.chunks, 1e9)).toEqual(clustered);
    expect(absorbSmallClusters(embeddings, clustered, f.chunks, 0)).toEqual(clustered);
  });
});

describe("average linkage", () => {
  /** The textbook O(n³) greedy: the closest pair of clusters merged, again and again. */
  function greedy(embeddings: Float32Array[]): number[] {
    const unit = embeddings.map((r) => {
      const n = Math.hypot(...r);
      return Array.from(r, (x) => x / n);
    });
    const dist = (i: number, j: number) => 1 - unit[i]!.reduce((s, x, k) => s + x * unit[j]![k]!, 0);
    const clusters = unit.map((_, i) => [i]);
    const heights: number[] = [];
    while (clusters.length > 1) {
      let best = [0, 1, Infinity];
      for (let a = 0; a < clusters.length; a += 1) {
        for (let b = a + 1; b < clusters.length; b += 1) {
          let sum = 0;
          for (const i of clusters[a]!) for (const j of clusters[b]!) sum += dist(i, j);
          const linkage = sum / (clusters[a]!.length * clusters[b]!.length);
          if (linkage < best[2]!) best = [a, b, linkage];
        }
      }
      heights.push(best[2]!);
      clusters[best[0]!] = [...clusters[best[0]!]!, ...clusters[best[1]!]!];
      clusters.splice(best[1]!, 1);
    }
    return heights;
  }

  it("finds the merge heights of the greedy order, sorted", () => {
    let state = 7;
    const random = () => ((state = (1103515245 * state + 12345) % 2147483648) / 2147483648) - 0.5;
    const embeddings = Array.from({ length: 60 }, () => Float32Array.from({ length: 8 }, random));
    const chain = averageLinkage(embeddings).map((m) => m.distance);
    const expected = greedy(embeddings);
    expect(chain.length).toBe(expected.length);
    chain.forEach((d, i) => expect(d).toBeCloseTo(expected[i]!, 9));
    for (let i = 1; i < chain.length; i += 1) expect(chain[i]!).toBeGreaterThanOrEqual(chain[i - 1]!);
  });

  it("clusters a thousand chunks quickly", () => {
    let state = 3;
    const random = () => ((state = (1103515245 * state + 12345) % 2147483648) / 2147483648) - 0.5;
    const centres = Array.from({ length: 5 }, () => Array.from({ length: 64 }, random));
    const embeddings = Array.from({ length: 1000 }, (_, i) => Float32Array.from(centres[i % 5]!, (x) => x + 0.3 * random()));
    const started = performance.now();
    const labels = agglomerative(embeddings);
    expect(performance.now() - started).toBeLessThan(5000);
    expect(new Set(labels).size).toBe(5);
  });
});
